    context = {},
    override = null,
    playlist = null,
    playlistSource = null,
    queue = [],
    index = -1,
    current = null,
    pending = null,
    dirty = false;
  let published = null,
    authored = null,
    remoteTracks = [],
    remoteSelection = null,
    lastPositionSecond = -1,
    notice = null,
    selectionNotice = null;
  let preparation = null;
  let savedPublicStyles = null,
    pendingPublicStyles = null,
    publicStyleLoad = null;
  let sourceManager = null,
    unsubscribeSources = null;
  let status = 'idle',
    error = null,
    desired = false,
    intentionallyPaused = false,
    disposed = false,
    suspended = false,
    volume = soundscape.getSettings().music,
    fade = 1,
    generation = 0,
    intentGeneration = 0,
    operation = null,
    pendingSeek = null;
  let failed = new Set(),
    fallbackUsed = false,
    failureFallback = null;
  let baseSelection = null,
    selectionLibrary = null;
  const gainLeases = new Map();
  const tracks = () => [
    ...soundtrackTracks(library),
    ...(authored ? [authored] : []),
    ...(published ? [published] : []),
    ...remoteTracks,
  ];
  const selectionContext = (value = context) => ({
    ...value,
    ...(!localPlayback && bundledIds.length ? { bundledTrackIds: bundledIds } : {}),
    ...(localPlayback
      ? {
          installedTrackIds: [
            ...new Set([
