      order: playlist?.order ?? null,
      repeat: playlist?.repeat ?? null,
      pendingPlaylistId: pending?.playlist.id ?? null,
      selection: override,
      source: pending?.source ?? resolve().source,
      queue: Object.freeze([...queue]),
      queueIndex: index,
