+  assert.match(h.player.snapshot().notice, /timed out/);
+  assert.equal(queue.snapshot().queued, 0);
+  assert.deepEqual(queue.snapshot().active, { fetch: 0, decode: 0, inspect: 0, main: 0 });
+  queue.setPhase('paused');
